Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class ConditionalAndResilientTests
{
    private string? _tempFile;

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Microsoft.Win32.Registry.GetValue(
            @"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void GpuRender_ProducesExpectedOutput()
    {
        var result = GpuRenderer.Render(scene);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await _weatherClient.GetForecastAsync();
        Assert.IsNotNull(forecast);
    }

    // 4. Cleanup temp files even on failure
    [TestMethod]
    public void Export_WritesToTempFile()
    {
        _tempFile = Path.GetTempFileName();
        File.WriteAllText(_tempFile, "data");

        var result = Importer.Read(_tempFile);
        Assert.AreEqual("data", result);
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Summary of attributes:**

| Scenario | Attribute/Pattern |
|----------|-------------------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` |
| Flaky external call | `[Retry(3)]` |
| Guaranteed cleanup | `[TestCleanup]` method |

**Key notes:**
- `[OSCondition]` and `[CICondition]` skip gracefully (not a failure) when the condition isn't met.
- `[Retry]` should only be used for genuinely flaky external dependencies — not to mask race conditions.
- `[TestCleanup]` runs after every test regardless of pass/fail, making it ideal for resource cleanup. You can also implement `IDisposable` on the test class for the same effect.
